import objarray2tidy = require( './index' );


// TESTS //

// The function returns a data set...
{
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data' ); // $ExpectType DataSet
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data', { 'a': 'x', 'b': 'y' } ); // $ExpectType DataSet
}

// The compiler throws an error if the function is provided a first argument which is not an array-like object containing objects...
{
	objarray2tidy( 5, 'data', { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( true, 'data', { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( false, 'data', { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( null, 'data', { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( {}, 'data', { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( ( x: number ): number => x, 'data', { 'a': 'x', 'b': 'y' } ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a string...
{
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 5, { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], true, { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], false, { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], null, { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], [], { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], {}, { 'a': 'x', 'b': 'y' } ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], ( x: number ): number => x, { 'a': 'x', 'b': 'y' } ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not an object...
{
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data', 5 ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data', true ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data', false ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data', null ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data', [ 1, 2 ] ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data', ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	objarray2tidy(); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ] ); // $ExpectError
	objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data', { 'a': 'x', 'b': 'y' }, {} ); // $ExpectError
}
